/// <summary>
/// CB434 - Batch completion task that updates GUPItemBasePrice.METItemPriceActivationStatus
/// after InventItemPriceActivationTaskActivateSim sub-tasks have finished.
/// InventItemPriceSim records are deleted during activation (moveSimulatedToCurrent), so
/// status is determined by checking InventItemPrice existence for each GUPItemBasePrice RecId.
/// </summary>
class METInventItemPriceActivationTaskComplete extends RunBaseBatch implements BatchRetryable
{
    List              basePriceRecIds = new List(Types::Int64);
    CostingVersionId  costingVersionId;
    int               pricesScheduledCount;
    TransDate         jobStartDate;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        costingVersionId,
        pricesScheduledCount,
        jobStartDate
    #endmacro

}

Method.Source:
public List parmBasePriceRecIds(List _basePriceRecIds = basePriceRecIds)
{
    basePriceRecIds = _basePriceRecIds;
    return basePriceRecIds;
}

public CostingVersionId parmCostingVersionId(CostingVersionId _costingVersionId = costingVersionId)
{
    costingVersionId = _costingVersionId;
    return costingVersionId;
}

public int parmPricesScheduledCount(int _pricesScheduledCount = pricesScheduledCount)
{
    pricesScheduledCount = _pricesScheduledCount;
    return pricesScheduledCount;
}

public TransDate parmJobStartDate(TransDate _jobStartDate = jobStartDate)
{
    jobStartDate = _jobStartDate;
    return jobStartDate;
}

public void run()
{
    GUPItemBasePrice    basePriceForStatus;
    InventDimId         priceInventDimId;
    int                 completedCount;
    int                 failedCount;
    int                 alreadyTerminalCount;
    TransDate           activationDate = jobStartDate ? jobStartDate : systemDateGet();

    ListIterator recIdIterator = new ListIterator(this.parmBasePriceRecIds());

    while (recIdIterator.more())
    {
        RecId basePriceRecId = recIdIterator.value();

        ttsbegin;

        select firstonly forupdate basePriceForStatus
            where basePriceForStatus.RecId == basePriceRecId;

        if (basePriceForStatus)
        {
            if (basePriceForStatus.METItemPriceActivationStatus == METItemPriceActivationStatus::Completed
                || basePriceForStatus.METItemPriceActivationStatus == METItemPriceActivationStatus::Skipped)
            {
                alreadyTerminalCount++;
                ttscommit;
                recIdIterator.next();
                continue;
            }

            InventItemPriceSim simCheck;
            select firstonly RecId from simCheck
                where simCheck.METGUPItemBasePriceId == basePriceRecId;

            if (!simCheck.RecId)
            {
                // Sim was deleted — verify InventItemPrice was actually created today
                priceInventDimId = InventTable::priceInventDimId(basePriceForStatus.ItemId, basePriceForStatus.InventDimId);

                InventItemPrice inventItemPriceCheck;
                select firstonly RecId from inventItemPriceCheck
                    where inventItemPriceCheck.ItemId         == basePriceForStatus.ItemId
                       && inventItemPriceCheck.VersionId      == costingVersionId
                       && inventItemPriceCheck.PriceType      == CostingVersionPriceType::Cost
                       && inventItemPriceCheck.InventDimId    == priceInventDimId
                       && inventItemPriceCheck.ActivationDate == activationDate;

                if (inventItemPriceCheck.RecId)
                {
                    basePriceForStatus.METItemPriceActivationStatus = METItemPriceActivationStatus::Completed;
                    completedCount++;
                }
                else
                {
                    basePriceForStatus.METItemPriceActivationStatus = METItemPriceActivationStatus::Failed;
                    failedCount++;
                }
            }
            else
            {
                basePriceForStatus.METItemPriceActivationStatus = METItemPriceActivationStatus::Failed;
                failedCount++;
            }

            basePriceForStatus.update();
        }

        ttscommit;

        recIdIterator.next();
    }

    if (costingVersionId)
    {
        ttsbegin;
        CostingVersion::updateLastActivation(costingVersionId);
        CostingVersion::updateLastUpdated(costingVersionId);
        ttscommit;
    }

    info(strfmt("Price activation complete: %1 activated, %2 failed, %3 already complete out of %4 scheduled.",
        completedCount,
        failedCount,
        alreadyTerminalCount,
        pricesScheduledCount));
}

public boolean unpack(container _packedClass)
{
    Version   version = RunBase::getVersion(_packedClass);
    container packedRecIds;

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, packedRecIds] = _packedClass;
            basePriceRecIds = packedRecIds ? List::create(packedRecIds) : new List(Types::Int64);
            break;
        default:
            return false;
    }

    return true;
}

public static METInventItemPriceActivationTaskComplete construct()
{
    return new METInventItemPriceActivationTaskComplete();
}

static ClassDescription description()
{
    return "Metcash - Activate future cost price (completion)";
}
